<?php require_once __DIR__.'/initiative-common.php'; $uid=initiativeUserId(); $id=(int)($_GET['id']??0); $i=initiativeLoad($id); $db=initiativeDb(); $w=$db->prepare("SELECT wi.*, wis.step_order,wis.status step_status,p.name position_name,ou.name unit_name,wis.comments FROM workflow_instances wi JOIN workflow_instance_steps wis ON wis.workflow_instance_id=wi.workflow_instance_id LEFT JOIN positions p ON p.position_id=wis.assigned_position_id LEFT JOIN organizational_units ou ON ou.unit_id=wis.assigned_unit_id WHERE wi.entity_type='INITIATIVE' AND wi.entity_id=:id ORDER BY wis.step_order");$w->execute(['id'=>$id]);$steps=$w->fetchAll();$a=$db->prepare("SELECT a.agreement_id,a.title,ia.relation_notes FROM initiative_agreements ia JOIN agreements a ON a.agreement_id=ia.agreement_id WHERE ia.initiative_id=:id");$a->execute(['id'=>$id]); initiativeHeader($i['title']); ?>
<h1><?=initiativeH($i['title'])?></h1><p><strong>Status:</strong> <?=initiativeH($i['status'])?></p><p><?=nl2br(initiativeH($i['description']))?></p><h2>Objectives</h2><p><?=nl2br(initiativeH($i['objectives']))?></p><?php if(initiativeCanEdit($i,$uid)):?><p><a class="button" href="initiative-edit.php?id=<?=$id?>">Edit</a></p><?php endif;?><form method="post" action="initiative-action.php"><input type="hidden" name="csrf" value="<?=initiativeCsrf()?>"><input type="hidden" name="initiative_id" value="<?=$id?>"><?php if(initiativeCanEdit($i,$uid)):?><button name="action" value="submit">Submit</button><?php endif;?><textarea name="comments" placeholder="Decision comments"></textarea><button name="action" value="approve">Approve current step</button><button name="action" value="request_changes">Request changes</button><button name="action" value="reject">Reject</button></form><h2>Approval path</h2><ol><?php foreach($steps as $s):?><li>Step <?=$s['step_order']?> — <?=initiativeH($s['position_name'] ?: 'Creator')?> — <?=initiativeH($s['step_status'])?></li><?php endforeach;?></ol><h2>Linked agreements</h2><ul><?php foreach($a as $r):?><li><?=initiativeH($r['title'])?><?= $r['relation_notes']?' — '.initiativeH($r['relation_notes']):''?></li><?php endforeach;?></ul><?php initiativeFooter(); ?>
